// WF-003 — Interpret Audio Service Result
// audio-service returns a normalized {ok,error:{code,message}} envelope, and
// the HTTP node above is set never to throw so we can actually read it.
// Re-throwing with a [[CODE]] marker is what lets WF-001 recover the
// *specific* code: n8n forwards only an error's message string to the parent
// workflow, so anything the caller needs has to live inside that message.
// The marker deliberately avoids a colon — n8n parses 'PREFIX: rest' as an
// error type and throws the prefix away (see WF-006's note).
//
// The case this exists for is ordinary, not exceptional: clips expire after
// AUDIO_RETENTION_MINUTES, so a user who records, gets distracted, and comes
// back will hit it. Without this they were told 'a downstream service failed',
// which is both wrong and unactionable — the fix is 'record it again'.
const item = $input.first().json || {};
const statusCode = item.statusCode || 200;
const body = item.body || {};
if (statusCode >= 400 || body.ok === false) {
  const err = body.error || {};
  // A missing clip is not an upstream failure -- it is an expected lifecycle
  // state with its own user-facing instruction.
  const code = (statusCode === 404 || err.code === 'NOT_FOUND')
    ? 'AUDIO_UNAVAILABLE'
    : (err.code || 'UPSTREAM_ERROR');
  throw new Error('[[' + code + ']] ' + (err.message || 'The audio could not be processed.'));
}
return [{ json: body }];
